const sidebar = document.querySelector('#ui-bar, .left, #sidebar') || document.body;
const canvases = [...document.querySelectorAll('canvas')].map(c=>{
  const r=c.getBoundingClientRect();
  return {id:c.id, cls:c.className, x:Math.round(r.x), y:Math.round(r.y), w:Math.round(r.width), h:Math.round(r.height)};
});
const info = {
  canvas_count: canvases.length,
  canvases: canvases.slice(0,6),
  Renderer_type: typeof Renderer,
  lastModel_name: (typeof Renderer!=='undefined' && Renderer.lastModel) ? Renderer.lastModel.name : null,
  has_composeLayers: (typeof Renderer!=='undefined') ? typeof Renderer.composeLayers : 'n/a',
  imgdiv: !!document.querySelector('#sidebar-canvas, .sidebar-canvas, #charCanvas')
};
return JSON.stringify(info);
